function openPanicSetup(showIntro=false){document.getElementById('panicSetupOverlay')?.remove();const overlay=document.createElement('div');overlay.className='panic-setup-overlay';overlay.id='panicSetupOverlay';overlay.innerHTML='<section class="panic-setup-card" role="dialog" aria-modal="true" aria-labelledby="panicSetupTitle"><div class="panic-setup-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 21 19H3L12 3Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M12 9v4.5M12 16.5v.1" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></div><div class="eyebrow">DIVISION QUICK SWITCH</div><h2 id="panicSetupTitle">'+(showIntro?'What is the Panic Key?':'Set your Panic Key destination')+'</h2><p class="panic-setup-copy" id="panicSetupCopy">'+(showIntro?'The Panic Key quickly replaces the current Division tab with a website you choose. If you skip choosing one, it uses Google Classroom by default. Your choice is saved on this browser.':'Choose a website to open when you press the Panic Key. Your destination is saved on this browser and can be changed in Settings.')+'</p><div id="panicSetupFormArea" '+(showIntro?'hidden':'')+'><form id="panicSetupForm" class="panic-setup-form"><label for="panicDestination">Website URL</label><input id="panicDestination" class="field" type="url" inputmode="url" placeholder="https://classroom.google.com/" value="'+esc(panicSavedUrl())+'" autocomplete="url"><p class="panic-setup-help">Enter a full website address starting with https:// or http://</p><button class="btn primary" type="submit">Save destination</button><button class="btn ghost" id="panicUseClassroom" type="button">Skip · Use Google Classroom</button></form></div><div class="panic-setup-actions" id="panicIntroActions" '+(showIntro?'':'hidden')+'><button class="btn primary" id="panicIntroOkay" type="button">Okay</button><button class="btn ghost" id="panicIntroSkip" type="button">Skip</button></div><p class="panic-setup-error" id="panicSetupError" role="alert" hidden></p></section>';document.body.appendChild(overlay);const formArea=overlay.querySelector('#panicSetupFormArea'),introActions=overlay.querySelector('#panicIntroActions'),title=overlay.querySelector('#panicSetupTitle'),copy=overlay.querySelector('#panicSetupCopy');const showForm=()=>{try{localStorage.setItem(PANIC_INTRO_KEY,'1')}catch{};formArea.hidden=false;introActions.hidden=true;title.textContent='Choose your Panic Key website';copy.textContent='Enter a website address below. If you skip, Google Classroom will be your saved destination.';overlay.querySelector('#panicDestination')?.focus()};if(showIntro){overlay.querySelector('#panicIntroOkay').onclick=showForm;overlay.querySelector('#panicIntroSkip').onclick=showForm}else overlay.querySelector('#panicDestination')?.focus();overlay.querySelector('#panicSetupForm').onsubmit=e=>{e.preventDefault();const input=overlay.querySelector('#panicDestination'),error=overlay.querySelector('#panicSetupError');if(!validPanicUrl(input.value)){error.textContent='Please enter a valid http:// or https:// website URL.';error.hidden=false;input.focus();return}if(!savePanicUrl(input.value)){error.textContent='Could not save this destination in your browser. Check browser storage settings.';error.hidden=false;return}overlay.remove();toast('Panic Key destination saved.')};overlay.querySelector('#panicUseClassroom').onclick=()=>{if(!savePanicUrl(PANIC_DEFAULT_URL)){const error=overlay.querySelector('#panicSetupError');error.textContent='Could not save in this browser. Please check browser storage settings.';error.hidden=false;return}overlay.remove();toast('Google Classroom saved as your Panic Key destination.')}}
